/* Alerts generated by the backend rules. Crew members see their own; the crew medical officer sees
   everyone's (or one astronaut's with ?astronauta=ID) and can acknowledge, resolve and reopen them. */
(async function () {
  "use strict";
  const S = window.Soma;
  const user = S.requireAuth();
  const main = document.getElementById("main");
  const staff = S.isStaff(user);
  S.renderShell("alerts", user);

  const astronautaId = S.targetAstronautId(user, { overview: true });   // null = staff overview of the whole crew
  const STATES = ["ACTIVA", "RECONOCIDA", "RESUELTA"];
  const PAGE_SIZE = 10;
  let alerts = [], total = 0, names = {}, astronauta = null;
  let stateFilter = "ALL", levelFilter = "ALL", page = 0;
  let maxTableHeight = 0;   // the table keeps the tallest height it has reached (a full page)
  let lastChange = null;   // { label, items: [{ id, previous }] } so the last action can be undone

  try {
    await load();
  } catch (e) {
    S.showError(main, e);
  }

  async function load() {
    if (astronautaId) {
      const [ctx, res] = await Promise.all([
        S.loadContext(astronautaId),
        S.api("/api/alertas/astronauta/" + encodeURIComponent(astronautaId) + "?size=500")
      ]);
      astronauta = ctx.astronauta;
      if (astronautaId === user.astronautaId) S.setRailName(astronauta.nombre);
      names[astronauta.id] = astronauta.nombre;
      alerts = res.contenido || [];
      total = res.totalElementos || alerts.length;
    } else {
      const [lista, ...pages] = await Promise.all([S.api("/api/astronautas")].concat(
        STATES.map(st => S.api("/api/alertas?estado=" + st + "&size=500"))));
      (lista || []).forEach(x => { names[x.id] = x.nombre; });
      alerts = pages.flatMap(p => p.contenido || []);
      total = pages.reduce((s, p) => s + (p.totalElementos || 0), 0);
    }
    alerts.sort((a, b) => S.toDate(b.fecha) - S.toDate(a.fecha));
    render();
  }

  function visible() {
    return alerts.filter(a => (stateFilter === "ALL" || a.estado === stateFilter) &&
      (levelFilter === "ALL" || a.severidad === levelFilter));
  }

  function actionsFor(a) {
    if (!staff) return "";
    const btn = (act, label) => '<button class="btn secondary small" data-act="' + act + '" data-id="' + S.esc(a.id) + '">' + label + "</button>";
    if (a.estado === "ACTIVA") return btn("reconocer", "Acknowledge");
    if (a.estado === "RECONOCIDA") return btn("resolver", "Resolve") + " " + btn("reactivar", "Reopen");
    return btn("reactivar", "Reopen");
  }

  function render() {
    const active = alerts.filter(a => a.estado === "ACTIVA");
    const activeCrit = active.filter(a => a.severidad === "CRITICA").length;
    const acknowledged = alerts.filter(a => a.estado === "RECONOCIDA").length;
    const rows = visible();
    const pages = Math.max(1, Math.ceil(rows.length / PAGE_SIZE));
    if (page > pages - 1) page = pages - 1;
    const slice = rows.slice(page * PAGE_SIZE, page * PAGE_SIZE + PAGE_SIZE);
    const showWho = !astronautaId;

    const stateChips = [["ALL", "All"], ["ACTIVA", "Active"], ["RECONOCIDA", "Acknowledged"], ["RESUELTA", "Resolved"]]
      .map(([v, l]) => '<button type="button" class="chip" data-state="' + v + '" aria-pressed="' + (stateFilter === v) + '">' + l + "</button>").join("");
    const levelChips = [["CRITICA", "Critical"], ["PRECAUCION", "Caution"], ["INFO", "Info"]]
      .map(([v, l]) => '<button type="button" class="chip" data-level="' + v + '" aria-pressed="' + (levelFilter === v) + '">' + l + "</button>").join("");

    const body = slice.length ? slice.map(a => {
      const lv = S.SEVERITY_LEVEL[a.severidad] || "none";
      const who = showWho ? '<td><a href="status.html?astronauta=' + encodeURIComponent(a.astronautaId) + '">' + S.esc(names[a.astronautaId] || "Unknown") + "</a></td>" : "";
      const handled = a.fechaAtencion ? '<div class="cell-sub">' + S.esc(S.fmtDateTime(a.fechaAtencion)) + "</div>" : "";
      return '<tr class="' + (a.estado === "RESUELTA" ? "dim" : "") + '">' +
        '<td class="cell-sub" style="white-space:nowrap">' + S.esc(S.fmtDateTime(a.fecha)) + "</td>" + who +
        '<td class="cell-strong">' + S.esc(S.alertText(a.mensaje)) + "</td>" +
        "<td>" + S.esc(S.ALERT_AREAS[a.tipo] || a.tipo || "—") + "</td>" +
        "<td>" + S.status(lv, S.SEVERITY_NAME[a.severidad]) + "</td>" +
        "<td>" + S.esc(S.ALERT_STATES[a.estado] || a.estado) + handled + "</td>" +
        '<td style="text-align:right;white-space:nowrap">' + actionsFor(a) + "</td></tr>";
    }).join("") : '<tr><td colspan="7" class="empty">No alerts match these filters.</td></tr>';
    // Keep the table at the height of a full page so the layout does not jump on the last page
    const fillers = '<tr class="filler" aria-hidden="true"><td colspan="7"></td></tr>'.repeat(Math.max(0, PAGE_SIZE - Math.max(slice.length, 1)));

    const subtitle = astronautaId
      ? astronauta.nombre + " · generated automatically from sensor and self-check data"
      : "All crew members · generated automatically from sensor and self-check data";
    const from = rows.length ? page * PAGE_SIZE + 1 : 0;
    const to = Math.min(rows.length, (page + 1) * PAGE_SIZE);

    main.innerHTML =
      (staff && astronautaId && astronautaId !== user.astronautaId ? S.viewingBanner(astronauta, "alerts") : "") +
      '<section class="page-head"><div><h1>Alerts</h1><p>' + S.esc(subtitle) + "</p></div>" +
      (staff ? '<div class="actions"><button class="btn" type="button" id="ack-all"' + (active.length ? "" : " disabled") + ">Acknowledge all active</button></div>" : "") +
      "</section>" +
      '<div id="msg">' + undoBar() + "</div>" +
      '<section class="tiles">' +
      tile("Active", active.length, "") + tile("Critical and active", activeCrit, activeCrit ? "crit" : "") +
      tile("Acknowledged", acknowledged, "") + tile("Total this mission", total, "dim") + "</section>" +
      '<section class="panel"><div class="panel-head" style="margin-bottom:14px"><div class="chips" role="group" aria-label="Filter">' +
      stateChips + '<span class="sep" aria-hidden="true"></span>' + levelChips + "</div>" +
      '<span class="note">Showing ' + from + "–" + to + " of " + rows.length + "</span></div>" +
      '<div class="table-wrap"><table class="data"><thead><tr><th>Time</th>' + (showWho ? "<th>Astronaut</th>" : "") +
      "<th>Alert</th><th>Area</th><th>Level</th><th>Status</th><th></th></tr></thead><tbody>" + body + fillers + "</tbody></table></div>" +
      '<div id="pager"></div></section>';

    const wrap = main.querySelector(".table-wrap");
    maxTableHeight = Math.max(maxTableHeight, wrap.offsetHeight);
    wrap.style.minHeight = maxTableHeight + "px";
    S.pager(document.getElementById("pager"), page, pages, p => { page = p; render(); main.querySelector(".panel").scrollIntoView({ block: "start" }); }, true);
    main.querySelectorAll("[data-state]").forEach(b => b.addEventListener("click", () => { stateFilter = b.dataset.state; page = 0; render(); }));
    main.querySelectorAll("[data-level]").forEach(b => b.addEventListener("click", () => {
      levelFilter = levelFilter === b.dataset.level ? "ALL" : b.dataset.level; page = 0; render();
    }));
    main.querySelectorAll("[data-act]").forEach(b => b.addEventListener("click", () => change([b.dataset.id], b.dataset.act, b)));
    const all = document.getElementById("ack-all");
    if (all) all.addEventListener("click", () => change(active.map(a => a.id), "reconocer", all));
    const undo = document.getElementById("undo");
    if (undo) undo.addEventListener("click", () => revert(undo));
  }

  function undoBar() {
    if (!lastChange) return "";
    return '<div class="notice info undo"><span class="grow">' + S.esc(lastChange.label) + "</span>" +
      '<button type="button" class="btn secondary small" id="undo">Undo</button></div>';
  }

  function tile(label, value, cls) {
    return '<div class="tile"><div class="label">' + S.esc(label) + '</div><div class="value ' + cls + '">' + value + "</div></div>";
  }

  async function patch(id, action) {
    const updated = await S.api("/api/alertas/" + encodeURIComponent(id) + "/" + action, { method: "PATCH" });
    const i = alerts.findIndex(a => a.id === id);
    if (i >= 0 && updated) alerts[i] = updated;
    return updated;
  }

  async function change(ids, action, button) {
    button.disabled = true;
    const items = ids.map(id => ({ id, previous: (alerts.find(a => a.id === id) || {}).estado }));
    const done = [];
    try {
      for (const it of items) { await patch(it.id, action); done.push(it); }
      const n = done.length, word = n === 1 ? "alert" : "alerts";
      const verb = { reconocer: "acknowledged", resolver: "resolved", reactivar: "reopened" }[action];
      lastChange = { label: n + " " + word + " " + verb + ".", items: done };
      render();
    } catch (e) {
      if (done.length) lastChange = { label: done.length + " alerts changed before an error.", items: done };
      render();
      S.showError(document.getElementById("msg"), e);
    }
  }

  /** Puts every alert of the last action back in the state it had before. */
  async function revert(button) {
    if (!lastChange) return;
    button.disabled = true;
    try {
      for (const it of lastChange.items) {
        const current = (alerts.find(a => a.id === it.id) || {}).estado;
        if (current === it.previous) continue;
        if (current !== "ACTIVA") await patch(it.id, "reactivar");
        if (it.previous === "RECONOCIDA") await patch(it.id, "reconocer");
        else if (it.previous === "RESUELTA") await patch(it.id, "resolver");
      }
      lastChange = null;
      render();
    } catch (e) {
      button.disabled = false;
      S.showError(document.getElementById("msg"), e);
    }
  }
})();
